{
  "compatibilityLevel": 1604,
  "model": {
    "culture": "en-US",
    "defaultPowerBIDataSourceVersion": "powerBI_V3",
    "expressions": [
      {
        "name": "WarehouseSource",
        "expression": "let database = Sql.Database(\"${WAREHOUSE_ENDPOINT}\", \"${ITEM_2}\") in database",
        "kind": "m"
      }
    ],
    "relationships": [
      {
        "name": "MovementsWarehouses",
        "fromColumn": "warehouse_id",
        "fromTable": "Activity",
        "toColumn": "warehouse_id",
        "toTable": "Locations"
      },
      {
        "name": "MovementsProducts",
        "fromColumn": "product_id",
        "fromTable": "Activity",
        "toColumn": "product_id",
        "toTable": "Items"
      }
    ],
    "tables": [
      {
        "name": "Activity",
        "columns": [
          {
            "name": "product_id",
            "dataType": "int64",
            "sourceColumn": "product_id",
            "summarizeBy": "none"
          },
          {
            "name": "movement_id",
            "dataType": "int64",
            "sourceColumn": "movement_id",
            "summarizeBy": "none"
          },
          {
            "name": "warehouse_id",
            "dataType": "int64",
            "sourceColumn": "warehouse_id",
            "summarizeBy": "none"
          },
          {
            "name": "units",
            "dataType": "int64",
            "sourceColumn": "units",
            "summarizeBy": "none"
          },
          {
            "name": "event_day",
            "dataType": "string",
            "sourceColumn": "event_day",
            "summarizeBy": "none"
          },
          {
            "name": "movement_type",
            "dataType": "string",
            "sourceColumn": "movement_type",
            "summarizeBy": "none"
          },
          {
            "name": "rate_version",
            "dataType": "int64",
            "sourceColumn": "rate_version",
            "summarizeBy": "none"
          },
          {
            "name": "unit_cost",
            "dataType": "int64",
            "sourceColumn": "unit_cost",
            "summarizeBy": "none"
          },
          {
            "name": "movement_value",
            "dataType": "int64",
            "sourceColumn": "movement_value",
            "summarizeBy": "none"
          }
        ],
        "measures": [
          {
            "name": "Handled Quantity",
            "expression": "SUM('Activity'[units])"
          },
          {
            "name": "Inbound Quantity",
            "expression": "CALCULATE([Handled Quantity],'Activity'[movement_type]=\"RECEIPT\")"
          },
          {
            "name": "Outbound Quantity",
            "expression": "CALCULATE([Handled Quantity],'Activity'[movement_type]=\"ISSUE\")"
          },
          {
            "name": "Inbound Fraction",
            "expression": "DIVIDE([Inbound Quantity],[Handled Quantity])"
          },
          {
            "name": "Quantity Balance",
            "expression": "[Inbound Quantity]-[Outbound Quantity]"
          },
          {
            "name": "Extended Value",
            "expression": "SUM('Activity'[movement_value])"
          },
          {
            "name": "Average Unit Value",
            "expression": "DIVIDE([Extended Value],[Handled Quantity])"
          },
          {
            "name": "Activity Entries",
            "expression": "COUNTROWS('Activity')"
          }
        ],
        "partitions": [
          {
            "name": "Activity",
            "mode": "directLake",
            "source": {
              "entityName": "movement_values",
              "expressionSource": "WarehouseSource",
              "schemaName": "dbo",
              "type": "entity"
            }
          }
        ]
      },
      {
        "name": "Locations",
        "columns": [
          {
            "name": "warehouse_id",
            "dataType": "int64",
            "sourceColumn": "warehouse_id",
            "summarizeBy": "none"
          },
          {
            "name": "warehouse_name",
            "dataType": "string",
            "sourceColumn": "warehouse_name",
            "summarizeBy": "none"
          }
        ],
        "partitions": [
          {
            "name": "Locations",
            "mode": "directLake",
            "source": {
              "entityName": "warehouse_locations",
              "expressionSource": "WarehouseSource",
              "schemaName": "dbo",
              "type": "entity"
            }
          }
        ]
      },
      {
        "name": "Items",
        "columns": [
          {
            "name": "product_id",
            "dataType": "int64",
            "sourceColumn": "product_id",
            "summarizeBy": "none"
          },
          {
            "name": "product_name",
            "dataType": "string",
            "sourceColumn": "product_name",
            "summarizeBy": "none"
          }
        ],
        "partitions": [
          {
            "name": "Items",
            "mode": "directLake",
            "source": {
              "entityName": "inventory_products",
              "expressionSource": "WarehouseSource",
              "schemaName": "dbo",
              "type": "entity"
            }
          }
        ]
      },
      {
        "name": "SupplierOrders",
        "columns": [
          {
            "name": "purchase_order_id",
            "dataType": "int64",
            "sourceColumn": "purchase_order_id",
            "summarizeBy": "none"
          },
          {
            "name": "warehouse_id",
            "dataType": "int64",
            "sourceColumn": "warehouse_id",
            "summarizeBy": "none"
          },
          {
            "name": "product_id",
            "dataType": "int64",
            "sourceColumn": "product_id",
            "summarizeBy": "none"
          },
          {
            "name": "ordered_units",
            "dataType": "int64",
            "sourceColumn": "ordered_units",
            "summarizeBy": "none"
          },
          {
            "name": "status",
            "dataType": "string",
            "sourceColumn": "status",
            "summarizeBy": "none"
          }
        ],
        "partitions": [
          {
            "name": "SupplierOrders",
            "mode": "directLake",
            "source": {
              "entityName": "purchase_orders",
              "expressionSource": "WarehouseSource",
              "schemaName": "dbo",
              "type": "entity"
            }
          }
        ]
      },
      {
        "name": "CountAdjustments",
        "columns": [
          {
            "name": "adjustment_id",
            "dataType": "int64",
            "sourceColumn": "adjustment_id",
            "summarizeBy": "none"
          },
          {
            "name": "movement_id",
            "dataType": "int64",
            "sourceColumn": "movement_id",
            "summarizeBy": "none"
          },
          {
            "name": "units",
            "dataType": "int64",
            "sourceColumn": "units",
            "summarizeBy": "none"
          },
          {
            "name": "reason_code",
            "dataType": "string",
            "sourceColumn": "reason_code",
            "summarizeBy": "none"
          }
        ],
        "partitions": [
          {
            "name": "CountAdjustments",
            "mode": "directLake",
            "source": {
              "entityName": "inventory_adjustments",
              "expressionSource": "WarehouseSource",
              "schemaName": "dbo",
              "type": "entity"
            }
          }
        ]
      }
    ]
  }
}
